import ast
import json
import re
from typing import List, Optional, Tuple

# Fixed palette mapping for integer grids
PALETTE = {
    0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
    5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
    9: "maroon", 10: "white", 11: "dark-gray"
}

def perceive(observation_history: list[str]) -> str:
    """
    Summarise the current grid observation with additional metadata
    (step, action count, center cell, action effect hints) so that
    the action between two consecutive states can be recovered.
    """
    obs = observation_history[-1] if observation_history else ""
    if not obs:
        return "empty_observation"

    try:
        # --- extract metadata (step, action count) ---
        step = _extract_meta(obs, "Step:")
        act_count = _extract_meta(obs, "Action count:")
        meta_parts = []
        if step is not None:
            meta_parts.append(f"step:{step}")
        if act_count is not None:
            meta_parts.append(f"act_count:{act_count}")

        # --- parse grid ---
        if "<grid_" in obs:
            grid = _parse_integer_grid(obs)
        else:
            grid = _parse_json_grid(obs)

        if grid is None or len(grid) == 0:
            return "empty_grid"

        # determine type and background
        if isinstance(grid[0][0], int):
            background = 0
            is_int = True
        else:
            background = "black"
            is_int = False

        # collect non‑background cells
        non_bg = []
        for r, row in enumerate(grid):
            for c, val in enumerate(row):
                if is_int:
                    if val != background:
                        non_bg.append((r, c, val))
                else:
                    if val.lower() != background:
                        non_bg.append((r, c, val.lower()))

        if not non_bg:
            return "all_black_grid"

        # --- mode, colour, agent, shape ---
        # detect white cells (agent)
        if is_int:
            white_val = 10
        else:
            white_val = "white"

        white_cells = [(r,c) for r,c,val in non_bg
                       if (is_int and val == white_val) or
                          (not is_int and val.lower() == white_val)]
        if white_cells:
            mode = "agent"
            agent = min(white_cells, key=lambda x: (x[0], x[1]))  # topmost
            shape_cells = non_bg
        else:
            mode = "no_agent"
            agent = None
            shape_cells = non_bg

        # colour of pattern (first non‑white cell if agent, else first cell)
        if mode == "agent":
            # find the first non‑white cell (the line colour)
            pattern_cells = [c for c in non_bg
                             if (is_int and c[2] != white_val) or
                                (not is_int and c[2].lower() != white_val)]
            if pattern_cells:
                first_col = pattern_cells[0][2]
            else:
                first_col = white_val  # fallback (all white)
        else:
            first_col = non_bg[0][2]

        if is_int:
            colour_name = PALETTE.get(first_col, f"code_{first_col}")
        else:
            colour_name = first_col.lower()

        # shape
        shape = _classify_shape(shape_cells)

        # centre cell (median row, median col of the 5 cells)
        centre = _get_centre(shape_cells)

        # --- action effects (domain knowledge) ---
        effects_str = _get_effects(mode, shape)

        # --- build output ---
        parts = meta_parts + [
            f"mode:{mode}",
            f"colour:{colour_name}",
            f"shape:{shape}",
        ]
        if agent:
            parts.append(f"agent({agent[0]},{agent[1]})")
        if centre:
            parts.append(f"centre({centre[0]},{centre[1]})")
        parts.append(f"effects:{effects_str}")

        # list cells (limit to stay under 2000 chars)
        max_cells = 200
        cell_strs = []
        for i, (r, c, val) in enumerate(non_bg):
            if i >= max_cells:
                cell_strs.append(f"+{len(non_bg)-max_cells}more")
                break
            if is_int:
                col_name = PALETTE.get(val, f"code_{val}")
            else:
                col_name = val
            cell_strs.append(f"({r},{c},{col_name})")

        parts.append("cells:" + ",".join(cell_strs))
        result = "; ".join(parts)
        if len(result) > 2000:
            result = result[:1997] + "..."
        return result

    except Exception as e:
        return f"parse_error:{str(e)[:100]}"


# -------------------------------------------------------------------
# Helper functions
# -------------------------------------------------------------------

def _extract_meta(obs: str, label: str) -> Optional[int]:
    """Extract an integer value after a label (e.g., 'Step: 55')."""
    pattern = re.escape(label) + r"\s*(\d+)"
    m = re.search(pattern, obs)
    if m:
        return int(m.group(1))
    return None


def _get_centre(cells: List[Tuple]) -> Optional[Tuple[int,int]]:
    """Return the median row and column of the cell list (assumes 5 cells)."""
    if not cells:
        return None
    rows = sorted([r for r,_,_ in cells])
    cols = sorted([c for _,c,_ in cells])
    # median is at index 2 (0‑based) if 5 cells, else middle of sorted
    mid_idx = len(rows)//2
    return (rows[mid_idx], cols[mid_idx])


def _get_effects(mode: str, shape: str) -> str:
    """Return a compact string describing the effect of each action
    on the shape & mode (based on known environment dynamics)."""
    if mode == "no_agent":
        if shape == "diagonal_inc":
            return "up:vertical, down:horizontal, left:diagonal_dec, right:diagonal_inc"
        elif shape == "diagonal_dec":
            return "up:horizontal, down:vertical, left:diagonal_dec, right:diagonal_inc"
        elif shape == "vertical":
            return "up:diagonal_dec, down:diagonal_inc, left:vertical, right:vertical"
        elif shape == "horizontal":
            return "up:diagonal_inc, down:diagonal_dec, left:horizontal, right:horizontal"
        else:
            return "unknown_shape"
    else:  # agent mode
        # moving the agent shifts all cells by (dr,dc); shape unchanged.
        # click removes agent, turns colour yellow.
        return "up:shift(-1,0), down:shift(1,0), left:shift(0,-1), right:shift(0,1), click:no_agent_yellow"


def _classify_shape(cells: list) -> str:
    """Classify the shape formed by the given cells (expect 5 collinear cells)."""
    if not cells:
        return "none"
    coords = [(r, c) for r, c, _ in cells]
    rows = [r for r, _ in coords]
    cols = [c for _, c in coords]

    if all(r == rows[0] for r in rows):
        return "horizontal"
    if all(c == cols[0] for c in cols):
        return "vertical"
    diff = [r - c for r, c in coords]
    if all(d == diff[0] for d in diff):
        return "diagonal_inc"
    summ = [r + c for r, c in coords]
    if all(s == summ[0] for s in summ):
        return "diagonal_dec"
    return "unknown_shape"


