def _get_effects(mode: str, shape: str) -> str:
    if mode == "agent":
        # Agent mode: movements translate all cells; click spawns a no_agent yellow shape.
        return ("up:shift(-1,0), down:shift(1,0), left:shift(0,-1), right:shift(0,1), "
                "click:mode=no_agent,colour=yellow,shape=" + shape)
    else:  # no_agent mode
