                    "click:mode=agent,colour=white,shape=diagonal_inc")
        elif shape == "diagonal_dec":
            return ("up:horizontal, down:vertical, left:diagonal_inc, right:diagonal_inc, "
                    "click:mode=agent,colour=white,shape=diagonal_dec")
        elif shape == "vertical":
            return ("up:diagonal_dec, down:diagonal_inc, left:vertical, right:vertical, "
