import ast
import json
from typing import List, Optional, Tuple

# -------------------------------------------------------------------
# Palette mapping (integer grids)
# -------------------------------------------------------------------
PALETTE = {
    0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
    5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
    9: "maroon", 10: "white", 11: "dark-gray"
}

# -------------------------------------------------------------------
# Main perceive function
# -------------------------------------------------------------------

def perceive(observation_history: list[str]) -> str:
    """
    Summarise the current grid observation.
    Output format:
      mode:<mode>; colour:<colour>; shape:<shape>; [agent(row,col);]
      [last_action:<action>;] cells:(r,c,colour),(...),...
    """
    if not observation_history:
        return "empty_observation"

    obs_current = observation_history[-1]

    # Parse current grid
    current_grid = _parse_any_grid(obs_current)
    if current_grid is None:
        return "parse_error:current_grid"

    # Compute the action that led from previous state to this one
    last_action = "none"
    if len(observation_history) >= 2:
        obs_prev = observation_history[-2]
        prev_grid = _parse_any_grid(obs_prev)
        if prev_grid is not None:
            last_action = _compute_action(prev_grid, current_grid)

    # Build the summary from the current grid
    summary = _build_summary(current_grid)
    if last_action != "none":
        summary["last_action"] = last_action

    # Format output
    parts = []
    parts.append(f"mode:{summary['mode']}")
    parts.append(f"colour:{summary['colour']}")
    parts.append(f"shape:{summary['shape']}")
    if summary['mode'] == 'agent':
        agent = summary['agent']
        parts.append(f"agent({agent[0]},{agent[1]})")
    if 'last_action' in summary:
        parts.append(f"last_action:{summary['last_action']}")
    # Cells list limited to 200 entries
    cells = summary['cells']
    max_cells = 200
    cell_strs = []
    for i, (r, c, col) in enumerate(cells):
        if i >= max_cells:
            cell_strs.append(f"+{len(cells)-max_cells}more")
            break
        cell_strs.append(f"({r},{c},{col})")
    parts.append("cells:" + ",".join(cell_strs))

    result = "; ".join(parts)
    if len(result) > 2000:
        result = result[:1997] + "..."
    return result

