# Grid parsing (handles both encodings)
# -------------------------------------------------------------------

def _parse_any_grid(obs: str) -> Optional[List[List]]:
    """Return a grid as list of list of ints (if integer) or strings (if JSON)."""
    if "<grid_" in obs:
        return _parse_integer_grid(obs)
    else:
        return _parse_json_grid(obs)

def _parse_integer_grid(obs: str) -> Optional[List[List[int]]]:
    """Extract the first grid block from an ARC‑style integer observation."""
    marker = "========== Start of Direct Observation =========="
    idx = obs.find(marker)
