def _compute_action(prev_grid: List[List], curr_grid: List[List]) -> str:
    """Determine the action that transformed prev_grid into curr_grid."""
    # Convert both to common representation: list of (r,c,colour) of non‑background cells
    prev_cells = _get_non_background_cells(prev_grid)
    curr_cells = _get_non_background_cells(curr_grid)

    # Helper to get color value (for comparison)
    def cell_val(cell):
        return cell[2]

    # Determine if each has an agent (white/10)
    def has_agent(cells):
        return any(cell_val(c) == "white" or cell_val(c) == 10 for c in cells)

    prev_has_agent = has_agent(prev_cells)
    curr_has_agent = has_agent(curr_cells)

    # Case: noop
    if _grids_equal(prev_grid, curr_grid):
        return "noop"

    # Case: click action (no agent -> agent)
    if not prev_has_agent and curr_has_agent:
        # Find the agent marker (topmost white cell)
        white_cells = [c for c in curr_cells if cell_val(c) == "white" or cell_val(c) == 10]
        if len(white_cells) >= 1:
            # Agent is topmost (smallest row), then leftmost
            agent = min(white_cells, key=lambda x: (x[0], x[1]))
            return f"click {agent[0]} {agent[1]}"
        else:
            return "click"  # fallback

    # Case: movement with agent
    if prev_has_agent and curr_has_agent:
        prev_white = [c for c in prev_cells if cell_val(c) == "white" or cell_val(c) == 10]
        curr_white = [c for c in curr_cells if cell_val(c) == "white" or cell_val(c) == 10]
        if prev_white and curr_white:
            # Agent is topmost white cell
            prev_agent = min(prev_white, key=lambda x: (x[0], x[1]))
            curr_agent = min(curr_white, key=lambda x: (x[0], x[1]))
            dr = curr_agent[0] - prev_agent[0]
            dc = curr_agent[1] - prev_agent[1]
            if dr == -1 and dc == 0:
                return "up"
            elif dr == 1 and dc == 0:
                return "down"
            elif dr == 0 and dc == -1:
                return "left"
            elif dr == 0 and dc == 1:
                return "right"
            else:
                # Possibly a click with movement? Not typical.
                # Fallback: infer from shape change
                return _infer_direction_from_shape(prev_cells, curr_cells)

    # Case: no agent on both -> shape pattern change
    return _infer_direction_from_shape(prev_cells, curr_cells)

def _get_non_background_cells(grid: List[List]) -> List[Tuple[int, int, str]]:
    """Return list of (row, col, colour_name) for cells not black."""
    if not grid:
        return []
    # Detect type
    if isinstance(grid[0][0], int):
        is_int = True
        background = 0
    else:
        is_int = False
        background = "black"

    cells = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if is_int:
                if val != background:
                    cells.append((r, c, PALETTE.get(val, f"code_{val}")))
            else:
                if val.lower() != background:
                    cells.append((r, c, val.lower()))
    return cells

def _grids_equal(g1: List[List], g2: List[List]) -> bool:
    """Check if two grids are identical."""
    if len(g1) != len(g2):
        return False
    for r in range(len(g1)):
        if len(g1[r]) != len(g2[r]):
            return False
        for c in range(len(g1[r])):
            if g1[r][c] != g2[r][c]:
                return False
    return True

def _infer_direction_from_shape(prev_cells: List[Tuple], curr_cells: List[Tuple]) -> str:
    """
    Infer left/right/up/down from the pattern of non‑background cells.
    Uses the fact that horizontal/vertical shifts and diagonal reflections are distinguishable.
    """
    # Build sets of coordinates
    prev_coords = {(r, c) for r, c, _ in prev_cells}
    curr_coords = {(r, c) for r, c, _ in curr_cells}

    # If same set -> noop (already handled)
    if prev_coords == curr_coords:
        return "noop"

    # Attempt translation detection
    # Compute possible translations that map prev to curr
    # Use a few representative points
    if prev_coords and curr_coords:
        sample_prev = list(prev_coords)[0]
        # Find corresponding point in curr (same colour)
        prev_col = [col for r, c, col in prev_cells if (r, c) == sample_prev][0]
        # Find all curr cells with that colour
        same_col_curr = [(r, c) for r, c, col in curr_cells if col == prev_col]
        if same_col_curr:
            # Try each match as translation
            for q in same_col_curr:
                dr = q[0] - sample_prev[0]
                dc = q[1] - sample_prev[1]
                # Check if all prev cells shifted by (dr, dc) land on curr cells
                if all((r+dr, c+dc) in curr_coords for r, c in prev_coords):
                    # Translation found
                    if dr == -1 and dc == 0:
                        return "up"
                    elif dr == 1 and dc == 0:
                        return "down"
                    elif dr == 0 and dc == -1:
                        return "left"
                    elif dr == 0 and dc == 1:
                        return "right"
                    else:
                        # Diagonal movement (shouldn't happen)
                        return "unknown"

    # If no translation, it's likely a diagonal mirror (left/right toggle)
    # Determine orientation of prev shape
    shape_prev = _classify_shape_list(prev_cells)
    shape_curr = _classify_shape_list(curr_cells)

    # Diagonal toggle: inc <-> dec
    if shape_prev in ("diagonal_inc", "diagonal_dec") and shape_curr in ("diagonal_inc", "diagonal_dec") and shape_prev != shape_curr:
        # Both left and right produce the same visual effect.
        # We cannot determine which from the two states alone.
        # Return a generic "toggle" but the last_action field will be filled from history.
        # However this function is called only when both grids are available,
        # and the actual action is recoverable from the previous step's output.
        # As a fallback, return "toggle" which indicates a left or right.
        # The downstream can use the last_action field from the second state.
        # For consistency, attempt to deduce using the pattern of coordinates.
        # The pattern is mirrored across vertical axis. We could compare the first cell's column change.
        # But left and right produce identical mirror. So return unknown.
        # Actually, in the environment, left always flips inc->dec and right flips dec->inc.
        # So we can use the direction of the flip.
        if shape_prev == "diagonal_inc" and shape_curr == "diagonal_dec":
            return "left"
        elif shape_prev == "diagonal_dec" and shape_curr == "diagonal_inc":
            return "right"
        else:
            return "toggle"  # fallback

    # For other shape changes (e.g., horizontal to diagonal)
    # We can compute the action by considering the known transition rules.
    # From the trajectory: up/down on horizontal produce diagonal_dec/diagonal_inc respectively.
    # But we can simply return "unknown" and let the historical last_action cover it.
    return "unknown"

def _classify_shape_list(cells: List[Tuple]) -> str:
    """Classify shape from a list of (r,c,col) cells (assuming 5 cells in a line)."""
    if len(cells) < 2:
        return "none"
    coords = [(r, c) for r, c, _ in cells]
    rows = [r for r, _ in coords]
    cols = [c for _, c in coords]
    # Horizontal
    if all(r == rows[0] for r in rows):
        return "horizontal"
    # Vertical
    if all(c == cols[0] for c in cols):
        return "vertical"
    # Diagonal increasing
    diff = [r - c for r, c in coords]
    if all(d == diff[0] for d in diff):
        return "diagonal_inc"
    # Diagonal decreasing
    summ = [r + c for r, c in coords]
    if all(s == summ[0] for s in summ):
        return "diagonal_dec"
    return "unknown_shape"

