# Summary building from a single grid
# -------------------------------------------------------------------

def _build_summary(grid: List[List]) -> dict:
    """Return a dict with mode, colour, shape, agent, cells."""
    if not grid:
        return {"mode": "empty", "colour": "none", "shape": "none", "cells": [], "agent": None}

    # Determine if integer or string
    if isinstance(grid[0][0], int):
        is_int = True
        background = 0
    else:
        is_int = False
        background = "black"

    # Collect non‑background cells
    non_bg = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if is_int:
                if val != background:
                    non_bg.append((r, c, PALETTE.get(val, f"code_{val}")))
            else:
                if val.lower() != background:
                    non_bg.append((r, c, val.lower()))

    # Determine mode (agent if white cells exist)
    white_cells = [(r, c) for r, c, col in non_bg
                   if col == "white" or col == 10]
    if white_cells:
        mode = "agent"
        agent = min(white_cells, key=lambda x: (x[0], x[1]))
        shape_cells = non_bg
    else:
        mode = "no_agent"
        agent = None
        shape_cells = non_bg

    # Colour: use first non‑bg cell's colour (ignore agent? but capture agent colour white)
    if non_bg:
        first_col = non_bg[0][2]
        colour = first_col
    else:
        colour = "none"

    # Shape
    shape = _classify_shape_list(shape_cells)

    return {
        "mode": mode,
        "colour": colour,
        "shape": shape,
        "agent": agent,
        "cells": non_bg
    }

