import ast
import json
from typing import List, Optional, Union, Tuple

# Fixed palette mapping for integer grids
PALETTE = {
    0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
    5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
    9: "maroon", 10: "white", 11: "dark-gray"
}

def perceive(observation_history: list[str]) -> str:
    """
    Summarise the current grid observation.
    The output includes:
    - step number and action count (if available)
    - mode (agent or no_agent)
    - colour of the pattern
    - shape classification
    - agent coordinates (if present)
    - list of all non-background cells from ALL grids, with grid index
    """
    obs = observation_history[-1] if observation_history else ""
    if not obs:
        return "empty_observation"

    try:
        # Extract metadata (step, levels completed, action count) if present
        step = _extract_field(obs, "Step:", int)
        action_count = _extract_field(obs, "Action count:", int)
        # Actually, extract action count, not step? Both useful.

        # Determine encoding and parse all grids
        if "<grid_" in obs:
            grids = _parse_integer_grids(obs)
        else:
            grids = _parse_json_grids(obs)

        if not grids:
            return "empty_grid"

        # Collect non‑background cells from all grids
        non_bg = []  # (grid_idx, r, c, colour_name)
        for grid_idx, grid in enumerate(grids):
            if grid is None or len(grid) == 0:
                continue
            # Determine if integer or string grid
            if isinstance(grid[0][0], int):
                background = 0
                is_int = True
            else:
                background = "black"
                is_int = False

            for r, row in enumerate(grid):
                for c, val in enumerate(row):
                    if is_int:
                        if val != background:
                            colour_name = PALETTE.get(val, f"code_{val}")
                            non_bg.append((grid_idx, r, c, colour_name))
                    else:
                        lower_val = val.lower()
                        if lower_val != background:
                            non_bg.append((grid_idx, r, c, lower_val))

        if not non_bg:
            return "all_black_grid"

        # Determine mode: agent present if any white cell exists
        white_cells = [(g, r, c) for g, r, c, col in non_bg if col == "white"]
        if white_cells:
            mode = "agent"
            # Agent is the topmost white cell (smallest row, then smallest col)
            agent = min(white_cells, key=lambda x: (x[1], x[2]))
            # agent is (grid, row, col)
        else:
            mode = "no_agent"
            agent = None

        # Determine pattern colour
        if mode == "agent":
            colour_name = "white"
        else:
            # Use colour of the first non‑background cell
            colour_name = non_bg[0][3]

        # Determine shape from all non‑background cells (including white for agent mode)
        shape_cells = [(r, c) for (_, r, c, _) in non_bg]  # ignore grid index for shape
        shape = _classify_shape(shape_cells)

        # Build output string
        parts = []

        # Optionally include step and action count
        if step is not None:
            parts.append(f"step:{step}")
        if action_count is not None:
            parts.append(f"action_count:{action_count}")

        parts.append(f"mode:{mode}")
        parts.append(f"colour:{colour_name}")
        parts.append(f"shape:{shape}")

        if agent:
            # agent is (grid, row, col) – we keep grid info if multiple grids? but fine
            parts.append(f"agent(g{agent[0]},{agent[1]},{agent[2]})")

        # List cells (limit to 200 to stay under 2000 chars)
        max_cells = 200
        cell_strs = []
        for i, (g, r, c, col) in enumerate(non_bg):
            if i >= max_cells:
                remaining = len(non_bg) - max_cells
                cell_strs.append(f"+{remaining}more")
                break
            cell_strs.append(f"(g{g},{r},{c},{col})")

        parts.append("cells:" + ",".join(cell_strs))
        result = "; ".join(parts)
        if len(result) > 2000:
            result = result[:1997] + "..."
        return result

    except Exception as e:
        # Never raise; return a safe fallback
        return f"parse_error:{str(e)[:100]}"

# -------------------------------------------------------------------
# Helper: extract a numeric field from text
# -------------------------------------------------------------------
def _extract_field(text: str, field_name: str, typ=float) -> Optional:
    """Extract the value after 'field_name' in the observation text."""
    idx = text.find(field_name)
    if idx == -1:
        return None
    idx += len(field_name)
    # skip spaces
    while idx < len(text) and text[idx] == ' ':
        idx += 1
    end = idx
    while end < len(text) and (text[end].isdigit() or text[end] == '.'):
        end += 1
    if end > idx:
        try:
            return typ(text[idx:end])
        except:
            pass
    return None

# -------------------------------------------------------------------
# Shape classification helper
# -------------------------------------------------------------------
def _classify_shape(coords: list) -> str:
    """Classify the shape formed by the given coordinates."""
    if not coords:
        return "none"
    rows = [r for r, _ in coords]
    cols = [c for _, c in coords]

    # Horizontal: all rows equal
    if all(r == rows[0] for r in rows):
        return "horizontal"
    # Vertical: all cols equal
    if all(c == cols[0] for c in cols):
        return "vertical"
    # Diagonal increasing: row - col constant
    diff = [r - c for r, c in coords]
    if all(d == diff[0] for d in diff):
        return "diagonal_inc"
    # Diagonal decreasing: row + col constant
    summ = [r + c for r, c in coords]
    if all(s == summ[0] for s in summ):
        return "diagonal_dec"
    return "unknown_shape"

# -------------------------------------------------------------------
# Parsing helpers for multiple grids
# -------------------------------------------------------------------

def _parse_integer_grids(obs: str) -> List[List[List[int]]]:
    """Extract all integer grids from the observation. Returns list of grids."""
    grids = []
    # Find start of direct observation
    marker = "========== Start of Direct Observation =========="
    idx = obs.find(marker)
    if idx == -1:
        # fallback: find first <grid>
        idx = obs.find("<grid_0>")
        if idx == -1:
            return grids
        # start parsing from there
        text = obs[idx:]
    else:
        text = obs[idx + len(marker):]

    # Split into lines
    lines = text.split("\n")
    current_grid = None
    for line in lines:
        s = line.strip()
        # Check for grid marker
        if s.startswith("<grid_"):
            if current_grid is not None:
                # save previous grid
                if current_grid:
                    grids.append(current_grid)
            current_grid = []
            continue
        # Skip empty lines before first grid
        if current_grid is None:
            continue
        # Parse a row: must look like [ ... ]
        if s.startswith("[") and s.endswith("]"):
            try:
                row = ast.literal_eval(s)
                if isinstance(row, list) and len(row) > 0:
                    current_grid.append(row)
                else:
                    # invalid row, end current grid
                    if current_grid:
                        grids.append(current_grid)
                    current_grid = []
            except:
                if current_grid:
                    grids.append(current_grid)
                current_grid = []
        else:
            # Non-row line ends current grid
            if current_grid:
                grids.append(current_grid)
                current_grid = []
    # Don't forget last grid
    if current_grid:
        grids.append(current_grid)
    return grids

def _parse_json_grids(obs: str) -> List[List[List[str]]]:
    """Extract the single JSON 2D array as a list of lists of colour names."""
    # Locate the outermost [[ ... ]]
    start = obs.find("[[")
    if start == -1:
        return []
    end = obs.rfind("]]")
    if end == -1:
        return []
    end += 2  # include the closing brackets

    json_str = obs[start:end]
    try:
        grid = json.loads(json_str)
        if isinstance(grid, list) and len(grid) > 0 and isinstance(grid[0], list):
            return [grid]
    except json.JSONDecodeError:
        pass
    return []
